using TdLib.TdApi;
using TdLib.TdApi.Objects;
namespace TdLib.Api.OpenTelemetry;
/// <summary>
/// Autogenerated TDLib APIs
/// </summary>

public partial class ClientOpenTelemetryDecorator
{
    /// <summary>
    /// Updates the game score of the specified user in the game; for bots only
    /// </summary>
    public Task<TdLib.TdApi.Objects.Message> SetGameScoreAsync(long chatId = default, long messageId = default, bool editMessage = default, long userId = default, int score = default, bool force = default)
    {

           using var activity =  StartCallActivity("SetGameScoreAsync", typeof(SetGameScore).FullName ?? "SetGameScoreAsync");

           try
           {
             return client.SetGameScoreAsync(chatId, messageId, editMessage, userId, score, force);
           }
           catch (Exception ex)
           {
               MarkAsError(activity, ex);
               throw;
           }
    }
}
